package manifest

import (
	"fmt"
	"path"
	"strconv"
	"strings"
)

// LocalRoot is the directory a project's own asset content lives under,
// relative to the project root.
//
// One directory rather than any path the author likes is what makes a local
// asset auditable: everything harnaas may read out of the repository is in one
// place, and a path that leaves it is a mistake harnaas can name without
// knowing anything about the project's layout.
const LocalRoot = ".harnaas"

// SourceKind names how harnaas obtains a source's content.
//
// The kind travels inside the source string rather than in a field of its own
// so a future kind slots into the one grammar instead of growing a second one.
// Parsing recognizes the kind and stops there — nothing here fetches, resolves
// or stats anything — so a manifest can be validated with no network and no
// filesystem, which is what lets `lint` report a bad source offline.
type SourceKind string

const (
	// SourceKindGitHub is a path within a GitHub repository at a ref.
	SourceKindGitHub SourceKind = "github"

	// SourceKindLocal is a path under the project's own `.harnaas` directory.
	SourceKindLocal SourceKind = "local"
)

// sourceKinds is every registered kind, in the order every message lists them.
//
// A slice rather than a map keeps that order identical on every run, which is
// what makes two people's terminals show the same diagnostic for the same file.
var sourceKinds = []SourceKind{SourceKindGitHub, SourceKindLocal}

// Source is one parsed `sources` entry: where a group of assets comes from,
// declared once and referenced by key.
//
// Nothing in it has been resolved. `Repository` is the text between the kind
// and the ref, checked for shape and not for existence, and `Ref` is the text
// after `@`, not a commit. Turning either into content is `install`'s job, and
// keeping it out of here is what makes validation a pure function of the file.
type Source struct {
	// Key is the short name asset entries reference. It is carried on the
	// parsed source so a diagnostic raised downstream can still name the
	// declaration that caused it.
	Key string

	// Kind is the registered kind, already checked against [sourceKinds].
	Kind SourceKind

	// Repository is what the kind names: an `owner/repository` pair for GitHub,
	// a project-relative directory under `.harnaas` for a local source.
	Repository string

	// Ref is the ref a GitHub source is pinned to, exactly as written. It is
	// empty for a local source, which has nothing to pin.
	Ref string
}

// String renders the source back in the form it was written, so a message can
// quote a parsed source without the caller reassembling it.
func (s Source) String() string {
	value := string(s.Kind) + ":" + s.Repository
	if s.Ref == "" {
		return value
	}
	return value + "@" + s.Ref
}

// ParseSource parses one `sources` value into its kind, repository and ref, and
// resolves nothing.
//
// The key is a parameter rather than something recovered from the value because
// every diagnostic here names it: an author reading "the source is malformed"
// has to find which one, and the map key is the only name the declaration has.
func ParseSource(key, value string) (Source, *Violation) {
	if violation := validateSourceKey(key); violation != nil {
		return Source{}, violation
	}

	kindText, remainder, hasKind := strings.Cut(value, ":")
	if !hasKind || kindText == "" || remainder == "" {
		return Source{}, sourceViolation(key,
			fmt.Sprintf("the source %q is %q, which does not name a source kind", key, value),
			fmt.Sprintf(
				"Write the value of %q in %s as a kind, a repository and a ref, as in %q.",
				key, FileName, "github:acme/assets@v1.2.0",
			),
		)
	}

	repository, ref := splitRef(remainder)

	// Every registered kind is listed, so a kind added to [sourceKinds] without
	// a case here reports itself as unrecognized rather than being parsed by
	// whichever branch happened to be last.
	switch SourceKind(kindText) {
	case SourceKindGitHub:
		return parseGitHubSource(key, repository, ref)
	case SourceKindLocal:
		return parseLocalSource(key, repository, ref)
	default:
		return Source{}, sourceViolation(key,
			fmt.Sprintf("the source %q names the kind %q, which harnaas does not recognize", key, kindText),
			fmt.Sprintf("Change %q in %s to use a kind harnaas knows: %s.", key, FileName, kindList()),
		)
	}
}

// parseGitHubSource checks the two things a GitHub source must state: which
// repository, and which ref.
func parseGitHubSource(key, repository, ref string) (Source, *Violation) {
	owner, name, hasOwner := strings.Cut(repository, "/")
	if !hasOwner || owner == "" || name == "" || strings.Contains(name, "/") {
		return Source{}, sourceViolation(key,
			fmt.Sprintf("the source %q names the repository %q, which is not an owner and a repository", key, repository),
			fmt.Sprintf(
				"Write the repository of %q in %s as owner/repository, as in %q.",
				key, FileName, "github:acme/assets@v1.2.0",
			),
		)
	}

	// A GitHub source with no ref is an unpinned dependency, and a manifest
	// whose whole purpose is declaring which version of somebody else's content
	// this repository trusts cannot have one. Defaulting to a branch would make
	// two installs of the same manifest produce different files.
	if ref == "" {
		return Source{}, sourceViolation(key,
			fmt.Sprintf("the source %q declares no ref, so it names no particular version of %q", key, repository),
			fmt.Sprintf(
				"Pin %q in %s to a tag or commit with an @ suffix, as in %q.",
				key, FileName, "github:acme/assets@v1.2.0",
			),
		)
	}

	return Source{Key: key, Kind: SourceKindGitHub, Repository: repository, Ref: ref}, nil
}

// parseLocalSource checks that a local source names a directory inside the
// project's `.harnaas`, and that it pins nothing.
func parseLocalSource(key, repository, ref string) (Source, *Violation) {
	if ref != "" {
		return Source{}, sourceViolation(key,
			fmt.Sprintf("the source %q is local and declares the ref %q, and content in this repository has no ref to be at", key, ref),
			fmt.Sprintf("Remove the %q suffix from %q in %s.", "@"+ref, key, FileName),
		)
	}

	cleaned, contained := containedUnderLocalRoot(repository)
	if !contained {
		return Source{}, sourceViolation(key,
			fmt.Sprintf("the source %q names the local path %q, which is not inside %s", key, repository, LocalRoot),
			fmt.Sprintf(
				"Point %q in %s at a directory under %s/, relative to the repository root.",
				key, FileName, LocalRoot,
			),
		)
	}

	return Source{Key: key, Kind: SourceKindLocal, Repository: cleaned}, nil
}

// validateSourceKey rejects a key an asset entry could not reference.
//
// The asset string grammar splits on the first colon, so a key containing one
// could never be written on an asset; a key containing a slash would be
// indistinguishable from a path. An empty key is rejected because the parsed
// asset reference uses an empty source key to mean the project-local form.
func validateSourceKey(key string) *Violation {
	switch {
	case key == "":
		return sourceViolation(key,
			"the "+quoted("sources")+" block declares an entry with an empty key",
			fmt.Sprintf("Give every entry in %s a short name, such as %q.", quoted("sources"), "acme"),
		)
	case !validSourceKey(key):
		return sourceViolation(key,
			fmt.Sprintf("the source key %q contains a character an asset entry could not reference it by", key),
			fmt.Sprintf(
				"Rename the key in %s to letters, digits, %q, %q or %q, such as %q.",
				FileName, "-", "_", ".", "acme",
			),
		)
	}
	return nil
}

// validSourceKey reports whether a key is one an asset entry could reference,
// which is the same question [validateSourceKey] answers with a diagnostic. The
// asset grammar asks it about text that may not be a key at all, where building
// a violation to discard would be the wrong shape.
func validSourceKey(key string) bool {
	return key != "" && !strings.ContainsAny(key, ":/\\ ")
}

// splitRef separates a ref from what precedes it, taking the last `@` so a
// repository containing one keeps it.
func splitRef(remainder string) (repository, ref string) {
	at := strings.LastIndex(remainder, "@")
	if at < 0 {
		return remainder, ""
	}
	return remainder[:at], remainder[at+1:]
}

// containedUnderLocalRoot reports whether a project-relative path stays inside
// `.harnaas`, returning it in cleaned form.
//
// The check runs on the text, before anything is opened, because a path that
// escapes must never be read — not even to discover that it exists. Cleaning
// first is what makes `.harnaas/../../etc` fail here rather than resolve
// somewhere it should not.
//
// A backslash is rejected outright rather than treated as a separator: it is an
// ordinary filename character on Linux and a separator on Windows, so a path
// containing one would mean two different things depending on who ran install.
func containedUnderLocalRoot(candidate string) (string, bool) {
	if candidate == "" || strings.ContainsRune(candidate, '\\') || strings.HasPrefix(candidate, "/") {
		return "", false
	}

	cleaned := path.Clean(candidate)
	if cleaned == LocalRoot || strings.HasPrefix(cleaned, LocalRoot+"/") {
		return cleaned, true
	}
	return "", false
}

// kindList renders the registered kinds for a diagnostic.
func kindList() string {
	names := make([]string, 0, len(sourceKinds))
	for _, kind := range sourceKinds {
		names = append(names, strconv.Quote(string(kind)))
	}
	return strings.Join(names, ", ")
}

// quoted renders a field or block name the way every diagnostic quotes one.
func quoted(name string) string {
	return strconv.Quote(name)
}

package cli

import (
	"os"
	"path/filepath"
	"slices"
	"strings"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/harness"
)

// harnessOrigin records how init arrived at a harness selection.
//
// The three origins are kept apart because each owes the user a different
// sentence: a flag-supplied list needs no explanation, a detected one is worth
// stating so a wrong guess is visible, and the default is the only case where
// harnaas chose a harness the project shows no sign of using.
type harnessOrigin int

const (
	// originFlag means the user named the harnesses explicitly.
	originFlag harnessOrigin = iota
	// originDetected means the project's own contents named them.
	originDetected
	// originDefault means nothing was detected and the roster's default was
	// used, because a manifest with an empty `harnesses` list would declare
	// assets and guarantee them for nothing.
	originDefault
)

// harnessSelection is the target list a scaffolded manifest will declare,
// together with how it was arrived at.
type harnessSelection struct {
	// Harnesses is the selection in the order it will be written, with
	// duplicates removed.
	Harnesses []harness.ID

	// Origin is how the list was arrived at.
	Origin harnessOrigin
}

// selectHarnesses resolves the manifest's `harnesses` list from what the user
// asked for and, failing that, from what the project shows.
//
// A flag-supplied list replaces detection entirely rather than adding to it.
// Merging the two would make the manifest depend on what happened to be in the
// working tree at the moment init ran, which is the opposite of what naming the
// harnesses explicitly asks for — and it would leave no way to scaffold a
// manifest that omits a harness the project already contains.
func selectHarnesses(root string, requested []string) (harnessSelection, error) {
	if len(requested) > 0 {
		ids, err := recognizedHarnesses(requested)
		if err != nil {
			return harnessSelection{}, err
		}
		return harnessSelection{Harnesses: ids, Origin: originFlag}, nil
	}

	if detected := detectHarnesses(root, harness.All()); len(detected) > 0 {
		return harnessSelection{Harnesses: detected, Origin: originDetected}, nil
	}

	return harnessSelection{Harnesses: []harness.ID{harness.Default}, Origin: originDefault}, nil
}

// recognizedHarnesses turns the flag's raw strings into roster ids, failing on
// the first name harnaas does not recognize.
//
// The roster's own error is returned unwrapped: it already names the input and
// lists what harnaas does recognize, which is the whole diagnostic, and the user
// is looking at the flag they just typed.
//
// A name repeated across flag occurrences is kept once. The manifest is a
// declaration rather than a log of what was typed, and a `harnesses` list naming
// one harness twice would be a file harnaas asked its author to hand-edit and
// then wrote badly itself.
func recognizedHarnesses(names []string) ([]harness.ID, error) {
	ids := make([]harness.ID, 0, len(names))
	for _, name := range names {
		id := harness.ID(name)
		if _, err := harness.Lookup(id); err != nil {
			return nil, err
		}
		if !slices.Contains(ids, id) {
			ids = append(ids, id)
		}
	}
	return ids, nil
}

// detectHarnesses reports which recognized harnesses the project already shows
// evidence of, in the roster's order.
//
// Detection reads and creates nothing: it stats the paths the roster declares as
// evidence and nothing else. That matters more here than it looks, because init
// runs before the project is under harnaas management at all — a detection pass
// that created a directory to look inside would be the one file init is
// forbidden to write.
//
// Order is the roster's rather than the filesystem's, so two projects containing
// the same harnesses scaffold the same list. The roster is a parameter for that
// clause alone: claude-code is the only entry today, so "every detected harness
// appears, in a deterministic order" has no case that exercises it, and the rule
// has to hold before the second harness is added rather than after.
func detectHarnesses(root string, roster []harness.Harness) []harness.ID {
	var detected []harness.ID
	for _, h := range roster {
		if usesHarness(root, h) {
			detected = append(detected, h.ID)
		}
	}
	return detected
}

// usesHarness reports whether any one of a harness's evidence paths exists in
// the project. Any single piece of evidence is enough — a project with a
// `CLAUDE.md` and no `.claude/` is still a project using Claude Code.
//
// The check is an Lstat rather than a Stat because the question is whether the
// harness left something behind, not whether that something resolves: a symlink
// named `.claude` pointing at a directory that is not checked out is still
// evidence, and following it would answer "no" for a project that plainly says
// yes.
func usesHarness(root string, h harness.Harness) bool {
	for _, evidence := range h.ProjectEvidence {
		if _, err := os.Lstat(filepath.Join(root, evidence)); err == nil {
			return true
		}
	}
	return false
}

// displayNames renders a selection the way it is said to a person, using the
// roster's display names rather than the ids the manifest will hold.
//
// An id that is somehow not on the roster falls back to itself rather than
// dropping out of the sentence: a selection is only ever built from recognized
// ids, and a message that silently listed fewer harnesses than it was about
// would be worse than one naming a raw id.
func displayNames(ids []harness.ID) string {
	names := make([]string, 0, len(ids))
	for _, id := range ids {
		h, err := harness.Lookup(id)
		if err != nil {
			names = append(names, string(id))
			continue
		}
		names = append(names, h.DisplayName)
	}
	return strings.Join(names, ", ")
}
=====PATHS=====
// Package paths establishes which project harnaas is acting on and carries it
// in the request context.
//
// Every path a command touches resolves against the project root, never against
// the process working directory: `harnaas install` run from `src/api/` has to
// install into the same places as the same command run from the repository
// root, and `harnaas lint` has to report the same findings from either. Reading
// the working directory at a use site quietly makes the answer depend on where
// the user happened to stand.
//
// So the root is resolved once, at the entrypoint, and read from the context
// everywhere else. forbidigo bans os.Getwd across the repository with a message
// naming ProjectRoot(ctx) as the replacement; WithDiscoveredRoot below is the
// single sanctioned reader of the working directory, and it exists only to feed
// that carrier. Nothing here resolves a root a second time.
package paths

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
)

// RepositoryMarker is the entry whose presence makes a directory the root of a
// repository. Git writes it as a directory in an ordinary clone and as a file in
// a worktree or a submodule, so the search below tests for existence and not for
// a directory — refusing to run inside a worktree would be an arbitrary
// restriction, not a safety property.
const RepositoryMarker = ".git"

// ErrRootNotEstablished reports that the context never passed through
// WithDiscoveredRoot or WithProjectRoot. It is a wiring failure rather than
// anything the user did: some caller built a context by hand and gave it to a
// command. The message still reads as a diagnostic because an error that can
// reach a terminal must, and it names the fix a developer needs.
var ErrRootNotEstablished error = rootNotEstablishedError{}

// rootNotEstablishedError carries ErrRootNotEstablished's message. It is a type
// rather than an errors.New value so the message can be a problem and a fix
// separated by a blank line, like every other diagnostic here, instead of the
// single unpunctuated clause a bare sentinel is held to.
type rootNotEstablishedError struct{}

func (rootNotEstablishedError) Error() string {
	return "no project root was established for this command\n\n" +
		"Build the command's context with paths.WithDiscoveredRoot before executing it."
}

// NoProjectRootError reports that Dir is not inside a repository, so there is no
// project for a command to act on.
//
// It is a type rather than a formatted string so a command can recognise the
// condition — `init` may want to say something about starting a repository
// where `lint` only wants to fail — without matching on message text.
type NoProjectRootError struct {
	// Dir is the absolute directory the upward search started from. Naming it
	// is most of the diagnostic: "not inside a repository" is puzzling until
	// the user sees which directory harnaas was actually looking at.
	Dir string
}

// Error states the problem and the edit that fixes it, in that order, as every
// user-facing diagnostic does.
func (e *NoProjectRootError) Error() string {
	return fmt.Sprintf(
		"no project root found: %s is not inside a repository\n\n"+
			"Run harnaas from inside your project's repository, or create one there with `git init`.",
		e.Dir,
	)
}

// rootKey is the context key for the resolved root. An unexported struct type
// cannot collide with a key from any other package.
type rootKey struct{}

// resolution is what the context carries: the root that was found, or the
// failure to find one.
//
// The failure travels rather than aborting at the entrypoint because most of
// what harnaas can do needs no project at all — `--version`, `--help`, an
// unknown-command diagnostic — and refusing to start outside a repository would
// break every one of them. A command that needs a root asks for one and gets the
// failure then, at the moment it is relevant.
type resolution struct {
	root string
	err  error
}

// Resolve walks up from startDir and returns the first enclosing directory
// holding a RepositoryMarker, or a *NoProjectRootError if the walk reaches the
// filesystem root without finding one.
//
// The nearest enclosing repository wins, so a command run inside a submodule
// acts on the submodule. That is the same answer git itself gives, and a rule
// that agrees with git is one users already know.
func Resolve(startDir string) (string, error) {
	dir, err := filepath.Abs(startDir)
	if err != nil {
		return "", fmt.Errorf("resolve %s to an absolute path: %w", startDir, err)
	}

	for {
		if _, err := os.Stat(filepath.Join(dir, RepositoryMarker)); err == nil {
			return dir, nil
		}

		parent := filepath.Dir(dir)
		if parent == dir {
			// filepath.Dir is its own fixed point at the filesystem root, and
			// on Windows at a volume root too, so this is the end of the walk
			// on every platform without special-casing either.
			return "", &NoProjectRootError{Dir: filepath.Clean(startDir)}
		}
		dir = parent
	}
}

// WithProjectRoot returns a context carrying root as the project root, for a
// caller that already knows it — a test over a scratch project, or a future
// command that resolves a project some other way.
func WithProjectRoot(ctx context.Context, root string) context.Context {
	return context.WithValue(ctx, rootKey{}, resolution{root: root})
}

// WithDiscoveredRoot resolves the project root from the process working
// directory and returns a context carrying either the root or the failure.
//
// This is the one place in harnaas that reads the working directory. It runs
// once, at the entrypoint, before any command executes; every other site calls
// ProjectRoot. Neither failure — an unreadable working directory or a directory
// outside any repository — is reported here, because at this point nobody knows
// yet whether the command about to run needs a project.
func WithDiscoveredRoot(ctx context.Context) context.Context {
	//nolint:forbidigo // The ban names ProjectRoot(ctx) as the replacement; this is the function that fills it, and the only sanctioned reader of the working directory.
	wd, err := os.Getwd()
	if err != nil {
		return context.WithValue(ctx, rootKey{}, resolution{
			err: fmt.Errorf("determine the working directory to resolve the project root from: %w", err),
		})
	}

	root, err := Resolve(wd)
	return context.WithValue(ctx, rootKey{}, resolution{root: root, err: err})
}

// ProjectRoot returns the project root carried by ctx.
//
// This is the replacement forbidigo's message names, and the only supported way
// to learn where the project is. A command that calls it is declaring that it
// needs a project, which is why the discovery failure surfaces here rather than
// at the entrypoint.
func ProjectRoot(ctx context.Context) (string, error) {
	res, ok := ctx.Value(rootKey{}).(resolution)
	if !ok {
		return "", ErrRootNotEstablished
	}
	if res.err != nil {
		return "", res.err
	}
	return res.root, nil
}

// Command harnaas manages a project's AI-harness assets as a declared,
// versioned dependency of the repository.
//
// This file owns the whole process contract: it is the only component that
// prints an error, the only one that chooses an exit code, and the only one
// that decides how a signal terminates the process. Commands return errors;
// what those errors look like on the terminal is decided here, once.
package main

import (
	"context"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"os"
	"os/signal"
	"runtime"
	"strings"
	"syscall"
	"time"

	"github.com/harnaas/harnaas/cmd/harnaas/cli"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/logging"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/paths"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/uiform"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/versioninfo"
	"github.com/harnaas/harnaas/internal/procsignal"
	"github.com/spf13/cobra"
)

// The exit-code contract. Every status harnaas can produce is listed here, and
// a new one must not be introduced without a documented meaning.
//
//   - exitSuccess       the command completed and found nothing to report.
//   - exitFailure       any runtime failure: bad configuration, I/O, network.
//   - exitLintFindings  reserved: `lint` ran its checks to completion and
//     reported at least one error-severity finding.
//
// exitLintFindings exists so a CI job can tell "lint crashed" from "lint worked
// and your harness has drifted" — the distinction lint exists to make. It is
// reserved for that single meaning: no command other than `lint` may return it,
// and a lint run that fails partway through exits exitFailure like any other
// runtime failure. Nothing in this binary emits it yet; `lint` itself arrives
// with add-harnaas-lint, and reportError below never produces it.
//
// Termination by signal is not in this list because it is not an exit at all:
// see dieFromSignal, which re-raises the signal and only falls back to
// 128-plus-signal-number where re-raising is unsupported.
const (
	exitSuccess      = 0
	exitFailure      = 1
	exitLintFindings = 2
)

// forceQuitGrace is how long dieFromSignal waits for a re-raised signal to be
// delivered. Delivery ends the process well before this elapses; the wait only
// exists so a platform that silently drops the re-raise still reaches the
// fallback exit instead of hanging.
const forceQuitGrace = 500 * time.Millisecond

func main() {
	// Resolve version and commit before anything reads them — the root command
	// copies Version into its own field as it is built.
	versioninfo.Load()

	os.Exit(run())
}

// run executes the command tree and returns the process exit code. It exists
// as a separate function so the deferred cancel actually runs; main's os.Exit
// would skip it.
func run() int {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	// Establish the project root once, here, so every command resolves paths
	// against the repository rather than against wherever the user was standing.
	// A failure to find one is carried in the context, not reported: `--version`
	// and `--help` are legitimate outside a repository, and only a command that
	// asks for a root should have to care that there is none.
	ctx = paths.WithDiscoveredRoot(ctx)

	// Diagnostics go to a log file for the rest of the run. Open reports no
	// failure because there is nowhere to report one to: the terminal belongs to
	// the command's own output, and a warning printed there is the interleaving
	// the file exists to avoid. A run whose log could not be opened just has no
	// log.
	closeLog := logging.Open()
	defer closeLog()

	logging.Info(ctx, "harnaas started", slog.String("version", versioninfo.Version))

	watchSignals(cancel, os.Stderr)

	root := cli.NewRootCmd()

	// ExecuteContextC returns the deepest command cobra matched, which is the
	// one whose usage a positional-argument error should show.
	executed, err := root.ExecuteContextC(ctx)
	if err == nil {
		logging.Info(ctx, "harnaas finished", slog.Int("exit_code", exitSuccess))
		return exitSuccess
	}

	if sig := terminatingSignal(err); sig != nil {
		logging.Info(ctx, "harnaas terminated by signal", slog.String("signal", sig.String()))
		cancel()
		dieFromSignal(sig)
	}

	code := reportError(root.ErrOrStderr(), root, executed, err)

	// The failure is recorded by type, never by message. Errors from later
	// phases quote the manifest that produced them, and a team's instructions
	// and rules are the content that must never reach a log file.
	logging.Error(ctx, "harnaas failed",
		slog.Int("exit_code", code),
		slog.String("error_type", fmt.Sprintf("%T", err)),
	)

	return code
}

// watchSignals installs the two-stage handler. The first signal cancels the
// root context so in-flight work unwinds cleanly and prints a notice; because
// signal.Notify has disabled Go's default "signal terminates the process"
// behaviour, a second read is what keeps a further Ctrl-C from being swallowed
// during a slow or stuck shutdown. The caught signal is recorded so the
// eventual termination re-raises that same signal rather than assuming an
// interrupt.
func watchSignals(cancel context.CancelFunc, notice io.Writer) {
	sigChan := make(chan os.Signal, 1)
	signals := []os.Signal{os.Interrupt}
	if runtime.GOOS != "windows" {
		signals = append(signals, syscall.SIGTERM)
	}
	signal.Notify(sigChan, signals...)

	go func() {
		sig := <-sigChan
		procsignal.Store(sig)
		fmt.Fprintln(notice, forceQuitNotice(sig))
		cancel()
		<-sigChan
		dieFromSignal(sig)
	}()
}

// forceQuitNotice is the advisory text for a first signal. It distinguishes an
// interrupt the user typed from a termination signal a supervisor sent, because
// the two want different explanations, and it leads with a blank line so the
// notice does not land on top of a half-written progress line.
func forceQuitNotice(sig os.Signal) string {
	if sig == os.Interrupt {
		return "\nInterrupting… press Ctrl-C again to force quit."
	}
	return "\nReceived termination signal, shutting down… signal again to force quit."
}

// terminatingSignal reports the signal that ended the run, or nil if it was not
// signal-driven.
//
// A prompt the user interrupted reports one even though no signal was ever
// delivered. A full-screen form puts the terminal in raw mode, and raw mode
// disables the line discipline's signal characters, so Ctrl-C reaches harnaas
// as a keystroke the form consumed instead of as SIGINT. The user pressed
// Ctrl-C; that the terminal was in a mode which does not translate it is not
// something they should have to know, and exiting normally would leave their
// Ctrl-C trapped inside a `while true` loop — the one outcome the re-raise in
// dieFromSignal exists to prevent.
//
// Otherwise the gate is deliberately on a signal having been recorded rather
// than on the error type alone: a context.Canceled that arose without a signal
// — an internally cancelled sub-context, say — is a genuine failure and must be
// reported as one, not dressed up as a user abort that would also wrongly break
// an enclosing shell loop.
func terminatingSignal(err error) os.Signal {
	if errors.Is(err, uiform.ErrInterrupted) {
		return os.Interrupt
	}
	if !errors.Is(err, context.Canceled) {
		return nil
	}
	return procsignal.Load()
}

// dieFromSignal terminates the process as if it had been killed by sig, rather
// than exiting normally.
//
// The distinction matters to an interactive shell: it aborts a
// `while true; do harnaas …; done` loop only when the child is *killed by*
// SIGINT. A plain exit with status 130 is an ordinary exit, so the loop keeps
// respawning harnaas and the user's Ctrl-C never escapes it. Re-raising the
// actual signal also keeps a SIGTERM shutdown reporting the conventional 143.
//
// The signal is reset to its default disposition, re-raised at this process,
// and given a moment to arrive. Where the re-raise cannot be delivered — on
// Windows, where signal-to-self is unsupported — the conventional
// 128-plus-signal-number exit is the fallback, so the process never hangs.
func dieFromSignal(sig os.Signal) {
	signal.Reset(sig)
	if p, err := os.FindProcess(os.Getpid()); err == nil {
		if err := p.Signal(sig); err == nil {
			time.Sleep(forceQuitGrace)
		}
	}
	os.Exit(exitCodeForSignal(sig))
}

// exitCodeForSignal maps a signal to the conventional 128-plus-signal-number
// exit code — 130 for SIGINT, 143 for SIGTERM — falling back to an interrupt's
// 130 for a signal carrying no numeric value on this platform.
func exitCodeForSignal(sig os.Signal) int {
	if s, ok := sig.(syscall.Signal); ok {
		return 128 + int(s)
	}
	return 128 + int(syscall.SIGINT)
}

// reportError renders err according to the error contract and returns the exit
// code the process should use. It is the single place that decides what a
// failure looks like on the terminal.
//
// root is the command tree's root and executed is the deepest command cobra
// matched; the two differ exactly when a subcommand's own validator failed,
// which is when the subcommand's usage — not the root's — is the useful one.
func reportError(out io.Writer, root, executed *cobra.Command, err error) int {
	var printed *cli.AlreadyPrintedError

	switch {
	case errors.As(err, &printed):
		// The command already wrote a friendly explanation. Printing anything
		// here would restate it in a less useful form.
	case isUnknownCommandOrFlagError(err):
		writeUsageAndError(out, root, err)
	case isPositionalArgError(err):
		writeUsageAndError(out, executed, err)
	default:
		fmt.Fprintln(out, err)
	}

	return exitFailure
}

// isUnknownCommandOrFlagError reports whether err is cobra's complaint about a
// verb or flag it does not recognise, which is a usage problem rather than a
// runtime one.
func isUnknownCommandOrFlagError(err error) bool {
	msg := err.Error()
	return strings.Contains(msg, "unknown command") || strings.Contains(msg, "unknown flag")
}

// isPositionalArgError reports whether err looks like a cobra positional-
// argument validator failure. Cobra's stock validators — ExactArgs, NoArgs,
// MinimumNArgs, MaximumNArgs, RangeArgs — all surface messages containing
// "arg(s)", and that substring appears in none of cobra's other error paths nor
// in harnaas's own errors, so it is a stable discriminator that does not reach
// into cobra internals.
func isPositionalArgError(err error) bool {
	return strings.Contains(err.Error(), "arg(s)")
}

// writeUsageAndError prints the command's usage before the error, so the reader
// sees what was expected and only then what went wrong.
func writeUsageAndError(out io.Writer, cmd *cobra.Command, err error) {
	if cmd == nil {
		fmt.Fprintln(out, err)
		return
	}
	fmt.Fprint(out, cmd.UsageString())
	fmt.Fprintf(out, "\nError: invalid usage: %v\n", err)
}
