package manifest_test

import (
	"testing"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/manifest"
)

// Scratch check: the example manifest printed in README.md must decode and
// interpret cleanly. Deleted after running; never committed.
func TestREADMEExampleManifest(t *testing.T) {
	const document = `{
  "version": 1,
  "harnesses": ["claude-code"],
  "sources": {
    "acme": "github:acme/ai-assets@v1.4.0",
    "house": "local:.harnaas/house"
  },
  "assets": [
    "acme:skills/code-review",
    "acme:instructions/tone.md",
    "house:rules/house-style.md",
    ".harnaas/rules/no-todo-comments.md",
    {
      "source": "acme:content/reviewer.md",
      "type": "persona",
      "id": "reviewer",
      "targets": ["claude-code"],
      "scope": "project"
    },
    {
      "source": "acme:commands/ship",
      "scope": "user"
    }
  ]
}`

	doc, err := manifest.Decode([]byte(document))
	if err != nil {
		t.Fatalf("decode: %v", err)
	}

	interpretation, err := manifest.Interpret(doc)
	if err != nil {
		t.Fatalf("interpret: %v", err)
	}

	for _, asset := range interpretation.Assets {
		t.Logf("index=%d type=%-11s id=%-16s scope=%-7s targets=%v source=%q path=%q",
			asset.Index, asset.Type, asset.ID, asset.Scope, asset.Targets,
			asset.Ref.SourceKey, asset.Ref.Path)
	}
}

