func TestAsSkillReplacesAnExistingInvocationKey(t *testing.T) {
	t.Parallel()

	out, err := render(requestFor(t, adapter.RendererAsSkill, manifest.AssetTypeCommand,
		"---\n"+autoInvokeKey+": true\nname: ship\n---\nBody.\n"))

