package cli

import (
	"fmt"
	"path"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/adapter"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/harness"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/manifest"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/source"
)

// sharedSkillsDir is the directory 17 of 23 surveyed harnesses read skills
// from, and the reason most harnesses need no adapter at all.
//
// A skill installs here once and is visible to every harness that reads it,
// rather than being copied into one directory per declared harness — which is
// what ADR 0002 chose and what makes the `harnesses` list a guarantee rather
// than an exclusion.
const sharedSkillsDir = ".agents/skills"

// pathScopingKey is the frontmatter key by which a rule narrows what it applies
// to. Its presence is what makes a rule impossible to emulate as an
// instruction.
const pathScopingKey = "paths"

// targetPlan is where one asset lands for one harness, and on what terms.
//
// A plan is produced for every asset-and-target pairing, including the ones
// nothing will be written for: an unsupported pairing is an outcome the report
// has to carry, not a pairing to drop silently.
type targetPlan struct {
	// Harness is the target, and Scope the root Destination is relative to.
	Harness harness.ID
	Scope   manifest.Scope

	// Destination is relative to the scope root, slash-separated. It is empty
	// for an instruction, which lands inside the memory file's managed block
	// rather than at a path of its own.
	Destination string

	// Renderer is the transformation selected for this pairing, and Emulated
	// records that it reaches the harness through another type's surface.
	Renderer adapter.Renderer
	Emulated bool

	// Tier and Note carry the surface's terms into the report.
	Tier adapter.Tier
	Note string

	// Instruction marks a pairing that contributes to the memory file's block.
	Instruction bool

	// Unsupported is why nothing will be written, and is empty for a pairing
	// that will be. A reason rather than a bool, because every one of them
	// names a different next action for the reader.
	Unsupported string
}

// supported reports whether anything will be written for this pairing.
func (p targetPlan) supported() bool { return p.Unsupported == "" }

// declaresPathScoping reports whether a rule narrows itself to particular
// paths.
//
// It reads the frontmatter textually and decodes nothing, because the only
// question is whether the key is there — and a decoder would have to be handed
// a type, which would mean agreeing on a schema for a document harnaas
// deliberately never rewrites.
func declaresPathScoping(content []byte) bool {
	matter, found := source.SplitFrontmatter(content)
	if !found {
		return false
	}
	for _, line := range splitLinesKeepingEndings(matter.Raw) {
		if declaresKey(line, pathScopingKey) {
			return true
		}
	}
	return false
}

// planTarget decides where one asset lands for one harness.
//
// The order of the branches is the design's two-tier support: a skill and an
// instruction reach every harness through shared locations and never consult an
// adapter, and only the three types with no shared equivalent do. That is why
// "a harness with no adapter" is a supported state rather than a gap — it costs
// such a harness nothing for the two types most projects declare.
func planTarget(asset manifest.Asset, files []source.File, target harness.ID, registry *adapter.Registry) targetPlan {
	plan := targetPlan{Harness: target, Scope: asset.Scope, Renderer: adapter.RendererIdentity}
	if plan.Scope == "" {
		plan.Scope = manifest.ScopeProject
	}

	switch asset.Type {
	case manifest.AssetTypeSkill:
		plan.Destination = path.Join(sharedSkillsDir, asset.ID)
		return plan

	case manifest.AssetTypeInstruction:
		// An instruction is inlined into the memory file's managed block, which
		// is one file for the whole project rather than one per asset, so it
		// has no destination of its own.
		plan.Instruction = true
		return plan

	case manifest.AssetTypeRule, manifest.AssetTypeCommand, manifest.AssetTypePersona:
	}

	adapted, err := registry.Lookup(target)
	if err != nil {
		plan.Unsupported = fmt.Sprintf(
			"%s has no harnaas adapter, and a %s reaches a harness only through one",
			target, asset.Type,
		)
		return plan
	}

	if destination, offered := adapted.Destination(asset); offered {
		return withSurface(plan, destination)
	}

	return emulate(plan, asset, files, adapted)
}

// withSurface fills a plan from the surface an adapter offered, refusing one the
// harness no longer reads.
//
// A removed surface is refused rather than written because writing there is a
// no-op that looks exactly like success — the file lands, the run is green, and
// the harness never opens it.
func withSurface(plan targetPlan, destination adapter.Destination) targetPlan {
	if destination.Tier == adapter.TierRemoved {
		plan.Unsupported = fmt.Sprintf(
			"%s no longer reads %s, so writing there would be a no-op that looks like success",
			plan.Harness, destination.Path,
		)
		if destination.Replacement != "" {
			plan.Unsupported += fmt.Sprintf(" (it reads %s instead)", destination.Replacement)
		}
		return plan
	}

	plan.Destination = destination.Path
	plan.Renderer = destination.Renderer
	plan.Tier = destination.Tier
	plan.Note = destination.Note
	return plan
}

// emulate decides whether an asset with no native surface can reach the harness
// through another type's, and refuses where doing so would change what the
// asset means.
//
// A native surface is always preferred, which is why this runs only after
// [adapter.Adapter.Destination] declined: emulation is the fallback, never a
// choice made while a real surface was available.
func emulate(plan targetPlan, asset manifest.Asset, files []source.File, adapted adapter.Adapter) targetPlan {
	switch asset.Type {
	case manifest.AssetTypeCommand:
		// A command delivered through the skill surface keeps its content and
		// loses only the harness's ability to start it unprompted, which the
		// renderer disables and the report states.
		if _, offered := adapted.Destination(skillAsset(asset)); !offered {
			plan.Unsupported = fmt.Sprintf("%s has no command surface and no skill surface to deliver one through", plan.Harness)
			return plan
		}
		plan.Destination = path.Join(sharedSkillsDir, asset.ID)
		plan.Renderer = adapter.RendererAsSkill
		plan.Emulated = true
		return plan

	case manifest.AssetTypeRule:
		if len(files) == 1 && declaresPathScoping(files[0].Content) {
			// Emulating this as an instruction would make a rule that applied
			// under some paths apply everywhere. That is a change of meaning
			// rather than of delivery, and it is invisible once written.
			plan.Unsupported = fmt.Sprintf(
				"%s has no rules directory, and this rule declares %q, "+
					"which the memory file cannot express: delivering it there would widen it from scoped to always-on",
				plan.Harness, pathScopingKey,
			)
			return plan
		}
		plan.Renderer = adapter.RendererAsInstruction
		plan.Emulated = true
		plan.Instruction = true
		return plan

	case manifest.AssetTypeSkill, manifest.AssetTypeInstruction, manifest.AssetTypePersona:
	}

	plan.Unsupported = fmt.Sprintf("%s has no surface for a %s and no way to deliver one without changing what it is",
		plan.Harness, asset.Type)
	return plan
}

// skillAsset is the asset as the skill surface would see it, used to ask an
// adapter whether it has one at all.
func skillAsset(asset manifest.Asset) manifest.Asset {
	asset.Type = manifest.AssetTypeSkill
	return asset
}

package cli

import (
	"cmp"
	"fmt"
	"slices"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/harness"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/manifest"
)

// outcome is what happened to one asset for one target.
//
// The set is closed and every pairing produces exactly one of them, including
// the pairings nothing was written for. A pairing that simply vanished from the
// report would be the silent no-op the whole design refuses: the reader would
// have no way to tell "installed" from "harnaas decided not to".
type outcome string

const (
	// outcomeCreated and outcomeUpdated are the two ways bytes landed.
	outcomeCreated outcome = "created"
	outcomeUpdated outcome = "updated"

	// outcomeUnchanged is reported rather than omitted, because "nothing to do"
	// is the answer a re-run exists to give.
	outcomeUnchanged outcome = "unchanged"

	// outcomeEmulated is an asset that reached the harness through another
	// type's surface. It is never reported as created or updated, because the
	// installed form behaves differently from a native one and the reader has
	// to know which they have.
	outcomeEmulated outcome = "emulated"

	// outcomeConflictUnmanaged is a destination that exists and no lockfile
	// entry claims. Nothing is written, on any flag.
	outcomeConflictUnmanaged outcome = "conflict-unmanaged"

	// outcomeConflictDrift is a managed destination edited since it was
	// installed. Nothing is written without --force.
	outcomeConflictDrift outcome = "conflict-drift"

	// outcomeUnsupported is a pairing harnaas will not write: a removed
	// surface, a renderer nobody implemented, or an emulation that would change
	// what the asset means.
	outcomeUnsupported outcome = "unsupported"
)

// outcomes is every outcome in report order, which runs from the ones that
// changed something to the ones that need a decision.
func outcomes() []outcome {
	return []outcome{
		outcomeCreated, outcomeUpdated, outcomeEmulated, outcomeUnchanged,
		outcomeConflictUnmanaged, outcomeConflictDrift, outcomeUnsupported,
	}
}

// blocked reports whether an outcome stopped or altered an install, which is
// exactly the set that must carry a remedy.
func (o outcome) blocked() bool {
	switch o {
	case outcomeConflictUnmanaged, outcomeConflictDrift, outcomeUnsupported, outcomeEmulated:
		return true
	case outcomeCreated, outcomeUpdated, outcomeUnchanged:
		return false
	}
	return false
}

// installResult is one asset-and-target pairing's line in the report.
type installResult struct {
	AssetID string             `json:"asset"`
	Type    manifest.AssetType `json:"type"`
	Harness harness.ID         `json:"harness"`
	Scope   manifest.Scope     `json:"scope"`

	// Destination is relative to the scope root, and is empty for an
	// instruction, which lands inside the memory file's block.
	Destination string `json:"destination,omitempty"`

	Outcome outcome `json:"outcome"`

	// Remedy is the command or manifest edit that resolves a blocked outcome,
	// and Note the sentence a gated surface or an emulation carries.
	Remedy string `json:"remedy,omitempty"`
	Note   string `json:"note,omitempty"`
}

// installReport is the whole run, in the order it is printed and encoded.
type installReport struct {
	Results []installResult `json:"results"`

	// Failures are the assets that could not be resolved at all, which is a
	// different thing from a pairing harnaas declined to write.
	Failures []installFailure `json:"failures,omitempty"`

	// DryRun records that nothing was written, so a JSON consumer cannot
	// mistake a plan for a run.
	DryRun bool `json:"dryRun"`
}

// installFailure is one asset that never reached the planning phase.
type installFailure struct {
	AssetID string `json:"asset"`
	Problem string `json:"problem"`
}

// sort puts the report in its stable order: by asset id, then type, then
// harness, then destination.
//
// Derived from identifiers rather than from manifest order or filesystem
// iteration order, so reordering the manifest changes neither the report nor
// the lockfile, and two runs over one project print the same thing.
func (r *installReport) sort() {
	slices.SortStableFunc(r.Results, func(a, b installResult) int {
		if byID := cmp.Compare(a.AssetID, b.AssetID); byID != 0 {
			return byID
		}
		if byType := cmp.Compare(string(a.Type), string(b.Type)); byType != 0 {
			return byType
		}
		if byHarness := cmp.Compare(string(a.Harness), string(b.Harness)); byHarness != 0 {
			return byHarness
		}
		return cmp.Compare(a.Destination, b.Destination)
	})
	slices.SortStableFunc(r.Failures, func(a, b installFailure) int {
		return cmp.Compare(a.AssetID, b.AssetID)
	})
}

// counts returns how many pairings each outcome covered, for the summary.
func (r *installReport) counts() map[outcome]int {
	counted := make(map[outcome]int, len(outcomes()))
	for _, result := range r.Results {
		counted[result.Outcome]++
	}
	return counted
}

// changed reports whether anything was written, which is what decides between
// a summary and "nothing to do".
func (r *installReport) changed() bool {
	for _, result := range r.Results {
		switch result.Outcome {
		case outcomeCreated, outcomeUpdated, outcomeEmulated:
			return true
		case outcomeUnchanged, outcomeConflictUnmanaged, outcomeConflictDrift, outcomeUnsupported:
		}
	}
	return false
}

// remedyFor is the runnable next step for a blocked outcome.
//
// Every one of them is a command to run or an edit to make, never a
// restatement of the problem: a reader who has just been told harnaas refused
// to do something needs the sentence that gets them unblocked.
func remedyFor(result installResult) string {
	switch result.Outcome {
	case outcomeConflictUnmanaged:
		return fmt.Sprintf(
			"harnaas never overwrites a path it did not create, --force included. "+
				"Move or delete %s yourself, then run `harnaas install` again.",
			result.Destination,
		)
	case outcomeConflictDrift:
		return fmt.Sprintf(
			"%s was edited since harnaas installed it. Run `harnaas install --force` to restore "+
				"the source content, or keep the edit and remove the asset from %s.",
			result.Destination, manifest.FileName,
		)
	case outcomeUnsupported:
		return fmt.Sprintf(
			"Nothing was written for this target. Narrow the entry's %q in %s so it does not name %s.",
			"targets", manifest.FileName, result.Harness,
		)
	case outcomeEmulated:
		return "No action is needed. This is reported separately from a native install because it behaves differently."
	case outcomeCreated, outcomeUpdated, outcomeUnchanged:
		return ""
	}
	return ""
}

package cli

import (
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path"
	"path/filepath"
	"strings"
	"time"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/jsonutil"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/source"
)

// installedFilePerm and installedDirPerm are the modes installed content is
// created with.
//
// Ordinary non-executable defaults: harness assets are documents, and an
// executable bit on one carries no meaning — which is also why file modes are
// not part of any digest.
const (
	installedFilePerm fs.FileMode = 0o644
	installedDirPerm  fs.FileMode = 0o755
)

// stagingSuffix and supersededSuffix name the two temporary neighbours a
// directory replacement uses. Both are removed on success and on failure, so a
// failed install leaves nothing behind for the next one to trip over.
const (
	stagingSuffix    = ".harnaas-staging"
	supersededSuffix = ".harnaas-superseded"
)

// installedState is what is on disk at a destination right now.
type installedState struct {
	// Present reports whether anything is there at all.
	Present bool

	// Files is a digest per file, relative to the destination and sorted by
	// path, in the shape the lockfile records.
	Files []lockFile

	// Digest covers the whole destination, computed the same way a resolved
	// source's is so the two are comparable at all.
	Digest source.Digest
}

// readInstalled reports what is at a destination, treating an absent one as
// simply not present.
//
// A file destination is read as a single entry named after its own leaf, which
// is how a resolved single-file source is shaped too — that symmetry is what
// lets one digest computation serve both sides of the comparison.
func readInstalled(root, destination string) (installedState, error) {
	full := filepath.Join(root, filepath.FromSlash(destination))

	info, err := os.Lstat(full)
	if errors.Is(err, fs.ErrNotExist) {
		return installedState{}, nil
	}
	if err != nil {
		return installedState{}, fmt.Errorf("read %s: %w", destination, err)
	}

	content := make(map[string][]byte)
	if info.IsDir() {
		if err := collectFiles(full, "", content); err != nil {
			return installedState{}, err
		}
	} else {
		//nolint:gosec // G304: the path is the resolved scope root plus a destination harnaas itself computed.
		data, readErr := os.ReadFile(full)
		if readErr != nil {
			return installedState{}, fmt.Errorf("read %s: %w", destination, readErr)
		}
		content[path.Base(destination)] = data
	}

	if len(content) == 0 {
		// A directory with nothing in it is not an installation. Treating it as
		// absent lets the next install create the content rather than compare
		// against a digest over no files.
		return installedState{}, nil
	}

	resolved, err := source.NewResolved(source.Provenance{}, content)
	if err != nil {
		return installedState{}, fmt.Errorf("digest %s: %w", destination, err)
	}

	files := make([]lockFile, 0, len(resolved.Files))
	for _, file := range resolved.Files {
		files = append(files, lockFile{Path: file.Path, Digest: file.Digest})
	}
	return installedState{Present: true, Files: files, Digest: resolved.Digest}, nil
}

// collectFiles reads every regular file beneath dir into content, keyed by its
// slash-separated path relative to the destination.
//
// A entry that is not a regular file is skipped rather than followed: a symlink
// inside a managed destination is not something harnaas put there, and reading
// through one would digest a file outside the destination as though it were in
// it.
func collectFiles(dir, prefix string, content map[string][]byte) error {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return fmt.Errorf("read %s: %w", dir, err)
	}
	for _, entry := range entries {
		name := path.Join(prefix, entry.Name())
		full := filepath.Join(dir, entry.Name())
		switch {
		case entry.IsDir():
			if err := collectFiles(full, name, content); err != nil {
				return err
			}
		case entry.Type().IsRegular():
			//nolint:gosec // G304: the path is beneath a destination harnaas computed and is walked, not taken from input.
			data, readErr := os.ReadFile(full)
			if readErr != nil {
				return fmt.Errorf("read %s: %w", full, readErr)
			}
			content[name] = data
		}
	}
	return nil
}

// writeDestination puts files at the destination, replacing whatever is there
// as a unit.
//
// A single file goes through the module's one atomic writer. A directory is
// staged beside its final location and moved into place, so the destination is
// never observed holding a mix of old and new files — the failure mode a
// file-by-file update has whenever a skill gains or loses a file.
func writeDestination(root, destination string, files []source.File) (err error) {
	full := filepath.Join(root, filepath.FromSlash(destination))

	if len(files) == 1 && files[0].Path == path.Base(destination) {
		if err := os.MkdirAll(filepath.Dir(full), installedDirPerm); err != nil {
			return fmt.Errorf("create the directory for %s: %w", destination, err)
		}
		if err := jsonutil.WriteFileAtomic(full, files[0].Content, installedFilePerm); err != nil {
			return fmt.Errorf("write %s: %w", destination, err)
		}
		return nil
	}

	staging := full + stagingSuffix
	if err := os.RemoveAll(staging); err != nil {
		return fmt.Errorf("clear the staging directory for %s: %w", destination, err)
	}
	defer func() {
		// Removed on both paths: a staging directory that outlived a failure is
		// the next run's mystery.
		if removeErr := os.RemoveAll(staging); err == nil && removeErr != nil {
			err = fmt.Errorf("remove the staging directory for %s: %w", destination, removeErr)
		}
	}()

	for _, file := range files {
		target := filepath.Join(staging, filepath.FromSlash(file.Path))
		if err := os.MkdirAll(filepath.Dir(target), installedDirPerm); err != nil {
			return fmt.Errorf("stage %s: %w", file.Path, err)
		}
		if err := os.WriteFile(target, file.Content, installedFilePerm); err != nil {
			return fmt.Errorf("stage %s: %w", file.Path, err)
		}
	}

	return swapIntoPlace(full, staging, destination)
}

// swapIntoPlace moves staging to full, stepping the previous content aside
// first.
//
// Renaming onto an existing directory fails on Windows and silently merges on
// none of the platforms harnaas ships to, so the previous content is renamed
// away and removed only once the new content is in place. A failure between the
// two puts the previous content back, which is what keeps the destination
// either wholly old or wholly new.
func swapIntoPlace(full, staging, destination string) error {
	if err := os.MkdirAll(filepath.Dir(full), installedDirPerm); err != nil {
		return fmt.Errorf("create the directory for %s: %w", destination, err)
	}

	superseded := full + supersededSuffix
	if err := os.RemoveAll(superseded); err != nil {
		return fmt.Errorf("clear the superseded directory for %s: %w", destination, err)
	}

	stepped := false
	if _, err := os.Lstat(full); err == nil {
		if err := os.Rename(full, superseded); err != nil {
			return fmt.Errorf("move the previous %s aside: %w", destination, err)
		}
		stepped = true
	}

	if err := os.Rename(staging, full); err != nil {
		if stepped {
			// Best effort, and the only correct one: the previous content is
			// the state the user had, and leaving the destination missing would
			// be worse than the failure being reported.
			_ = os.Rename(superseded, full)
		}
		return fmt.Errorf("move %s into place: %w", destination, err)
	}

	if stepped {
		if err := os.RemoveAll(superseded); err != nil {
			return fmt.Errorf("remove the previous %s: %w", destination, err)
		}
	}
	return nil
}

// removeDestination deletes a managed destination and any directories it leaves
// empty beneath the scope root.
//
// Pruning the empty parents matters because the shared skills directory is
// created by harnaas and would otherwise linger after a full uninstall, looking
// like something a harness still reads. It stops at the scope root and at the
// first directory that still holds anything.
func removeDestination(root, destination string) error {
	full := filepath.Join(root, filepath.FromSlash(destination))
	if err := os.RemoveAll(full); err != nil {
		return fmt.Errorf("remove %s: %w", destination, err)
	}

	for dir := filepath.Dir(full); strings.HasPrefix(dir, root) && dir != root; dir = filepath.Dir(dir) {
		entries, err := os.ReadDir(dir)
		if err != nil || len(entries) > 0 {
			return nil
		}
		if err := os.Remove(dir); err != nil {
			return nil
		}
	}
	return nil
}

// lockFileName is the exclusive lock covering the lockfile's read-modify-write.
const lockLockFileName = ".harnaas.lock"

// lockWait and lockPoll bound how long a run waits for another to finish.
//
// Bounded rather than indefinite because the primary consumers are CI jobs and
// coding agents: a run that blocks forever behind a crashed one is a hung job
// nobody is watching, and a clear message naming the holder is something a
// reader can act on.
const (
	lockWait = 10 * time.Second
	lockPoll = 100 * time.Millisecond
)

// lockContentionError reports another run holding the install lock.
type lockContentionError struct {
	Path string
}

func (e *lockContentionError) Error() string {
	return fmt.Sprintf(
		"another harnaas install is running in this project (its lock is %s)\n\n"+
			"Wait for it to finish and run again. If no install is running, that file is left over "+
			"from one that was killed, and deleting it is safe.",
		e.Path,
	)
}

// acquireInstallLock takes the exclusive lock, waiting a bounded time for it.
//
// The lock is a file created with O_EXCL, which is atomic on every platform
// harnaas ships to and needs no dependency. What it guards is the lockfile's
// read-modify-write: two installs interleaving there would write a lockfile
// recording one run's assets and the other's installations.
func acquireInstallLock(root string) (func(), error) {
	full := filepath.Join(root, lockLockFileName)

	deadline := time.Now().Add(lockWait)
	for {
		file, err := os.OpenFile(full, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o600)
		if err == nil {
			_ = file.Close()
			return func() { _ = os.Remove(full) }, nil
		}
		if !errors.Is(err, fs.ErrExist) {
			return nil, fmt.Errorf("take the install lock: %w", err)
		}
		if time.Now().After(deadline) {
			return nil, &lockContentionError{Path: full}
		}
		time.Sleep(lockPoll)
	}
}

