package cli

import (
	"cmp"
	"slices"
)

// severity is how much a finding matters, and it decides the exit status.
//
// There are two, deliberately. A third — "info" — would be a finding nobody has
// to act on, and a report that contains those teaches a reader to skim past the
// line that mattered.
type severity string

const (
	// severityError is every state that is not both pinned and current. It
	// exits 2.
	severityError severity = "error"

	// severityWarning is advisory and leaves the installation reproducible and
	// current. It exits 0 unless --strict.
	severityWarning severity = "warning"
)

// finding is one discrepancy lint found.
//
// Every field but Asset and Path is required, including Remedy: a finding with
// no available remedy says so rather than omitting the field, because a reader
// who meets a blank there cannot tell "nothing to do" from "harnaas forgot".
type finding struct {
	// Asset is the asset the finding concerns, empty for a project-level one
	// such as a managed block.
	Asset string `json:"asset,omitempty"`

	// Path is the specific file, where one file of an installation is at fault
	// rather than the whole of it.
	Path string `json:"path,omitempty"`

	Severity severity `json:"severity"`
	Problem  string   `json:"problem"`
	Remedy   string   `json:"remedy"`
}

// lintReport is everything one run found.
type lintReport struct {
	Findings []finding `json:"findings"`

	// Unchecked names the assets update detection could not reach, and Skipped
	// the checks that did not run at all.
	//
	// Both exist so a clean report is never mistaken for a complete one. A run
	// that could not reach the network and said nothing would be reporting
	// "everything is current" on the strength of not having looked.
	Unchecked []string `json:"unchecked,omitempty"`
	Skipped   []string `json:"skipped,omitempty"`
}

// sort puts findings in their stable order: by asset, then path, then problem.
//
// Derived from the finding rather than from the order the checks ran, so
// reordering the manifest or the lockfile cannot reorder the report and two
// runs over identical state are identical line for line.
func (r *lintReport) sort() {
	slices.SortStableFunc(r.Findings, func(a, b finding) int {
		if byAsset := cmp.Compare(a.Asset, b.Asset); byAsset != 0 {
			return byAsset
		}
		if byPath := cmp.Compare(a.Path, b.Path); byPath != 0 {
			return byPath
		}
		return cmp.Compare(a.Problem, b.Problem)
	})
	slices.Sort(r.Unchecked)
	slices.Sort(r.Skipped)
}

// counts returns how many findings carried each severity.
func (r *lintReport) counts() (errors, warnings int) {
	for _, found := range r.Findings {
		switch found.Severity {
		case severityError:
			errors++
		case severityWarning:
			warnings++
		}
	}
	return errors, warnings
}

// LintFindingsError reports that lint ran its checks to completion and found at
// least one error-severity finding.
//
// It is a type of its own so the entrypoint can tell it from every other
// failure and exit 2 rather than 1. That distinction is the whole reason the
// status is reserved: a CI job has to be able to tell "lint crashed" from "lint
// worked and your harness has drifted", and a lint run that fails partway
// through is the former.
type LintFindingsError struct {
	// Errors is how many error-severity findings were reported, so the
	// entrypoint's log record says how bad it was without re-reading the
	// report.
	Errors int
}

func (e *LintFindingsError) Error() string {
	return "lint found problems"
}

// AlreadyPrinted reports that the findings have been written, so the entrypoint
// adds nothing. The report *is* the message.
func (e *LintFindingsError) AlreadyPrinted() bool { return true }

package cli

import (
	"fmt"
	"strings"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/manifest"
)

// checkNothingInstalled collapses "nothing has been installed yet" into one
// finding.
//
// A fresh clone declaring twelve assets would otherwise report twelve identical
// "not installed" findings, which buries the one thing the reader needs to know
// and the one command that fixes all of it. The absent lockfile is deliberately
// not a finding of its own: it is not a second problem, it is the same one.
func checkNothingInstalled(declared []manifest.Asset, recorded *lockDocument) (finding, bool) {
	if len(declared) == 0 || len(recorded.Assets) > 0 {
		return finding{}, false
	}
	return finding{
		Severity: severityError,
		Problem: fmt.Sprintf("%d declared %s not been installed in this project yet",
			len(declared), plural(len(declared), "asset has", "assets have")),
		Remedy: "Run `harnaas install`.",
	}, true
}

// checkDeclaredButNotInstalled reports an asset the manifest declares and the
// lockfile does not record.
func checkDeclaredButNotInstalled(declared []manifest.Asset, recorded *lockDocument) []finding {
	known := previousAssets(recorded)

	var findings []finding
	for _, asset := range declared {
		if _, found := known[assetKey{ID: asset.ID, Type: asset.Type}]; found {
			continue
		}
		findings = append(findings, finding{
			Asset:    asset.ID,
			Severity: severityError,
			Problem:  fmt.Sprintf("%q is declared in %s and has never been installed", asset.ID, manifest.FileName),
			Remedy:   "Run `harnaas install`.",
		})
	}
	return findings
}

// checkRecordedButUndeclared reports a lockfile entry the manifest no longer
// declares.
//
// The remedy is the install command rather than an edit, because install is
// what converges: removing the entry by hand would leave the installed files
// behind and unmanaged.
func checkRecordedButUndeclared(declared []manifest.Asset, recorded *lockDocument) []finding {
	wanted := make(map[assetKey]bool, len(declared))
	for _, asset := range declared {
		wanted[assetKey{ID: asset.ID, Type: asset.Type}] = true
	}

	var findings []finding
	for _, asset := range recorded.Assets {
		if wanted[assetKey{ID: asset.ID, Type: asset.Type}] {
			continue
		}
		findings = append(findings, finding{
			Asset:    asset.ID,
			Severity: severityError,
			Problem: fmt.Sprintf("%q is recorded as installed and %s no longer declares it",
				asset.ID, manifest.FileName),
			Remedy: "Run `harnaas install`, which removes what is no longer declared.",
		})
	}
	return findings
}

// checkRefDisagreement reports a lockfile whose recorded ref differs from what
// the manifest now asks for.
//
// This is the check frozen mode exists for: it needs no installed files and no
// network, and it catches the common case of somebody editing a ref and not
// reinstalling before opening a pull request.
func checkRefDisagreement(declared []manifest.Asset, sources map[string]manifest.Source, recorded *lockDocument) []finding {
	known := previousAssets(recorded)

	var findings []finding
	for _, asset := range declared {
		was, found := known[assetKey{ID: asset.ID, Type: asset.Type}]
		if !found {
			continue
		}
		wanted := sources[asset.Ref.SourceKey].Ref
		if wanted == "" || wanted == was.RequestedRef {
			continue
		}
		findings = append(findings, finding{
			Asset:    asset.ID,
			Severity: severityError,
			Problem: fmt.Sprintf("%s asks for %q and the lockfile records %q as installed",
				manifest.FileName, wanted, was.RequestedRef),
			Remedy: "Run `harnaas install` to install the ref the manifest asks for.",
		})
	}
	return findings
}

// checkNotReproducible reports an asset tracking a ref that can move.
//
// It is an error whether or not the ref has moved, and that is the point. A
// branch moves whenever upstream commits, so reporting a moved branch as
// "outdated" would leave CI permanently red with no achievable fix; reporting
// it as "not pinned" gives a fix the team can actually apply once. See ADR
// 0004.
func checkNotReproducible(declared []manifest.Asset, sources map[string]manifest.Source) []finding {
	var findings []finding
	for _, asset := range declared {
		source, found := sources[asset.Ref.SourceKey]
		if !found || source.Kind != manifest.SourceKindGitHub {
			continue
		}
		if looksLikeCommit(source.Ref) || looksLikeVersionTag(source.Ref) {
			continue
		}
		findings = append(findings, finding{
			Asset:    asset.ID,
			Severity: severityError,
			Problem: fmt.Sprintf("%q tracks %q, which can point somewhere else tomorrow, so this install is not reproducible",
				asset.ID, source.Ref),
			Remedy: fmt.Sprintf(
				"Pin it in %s: change the %q source to a version tag or a full commit identifier, then run `harnaas install`.",
				manifest.FileName, asset.Ref.SourceKey),
		})
	}
	return findings
}

// looksLikeCommit reports whether a ref is a full commit identifier, which is
// the one ref that cannot move.
//
// Only a full one counts: an abbreviation names whichever object it is unique
// against today, so one that grew a second match upstream would silently become
// a different install.
func looksLikeCommit(ref string) bool {
	if len(ref) != 40 {
		return false
	}
	for _, char := range ref {
		if !strings.ContainsRune("0123456789abcdefABCDEF", char) {
			return false
		}
	}
	return true
}

// looksLikeVersionTag reports whether a ref is a version tag.
//
// The test is deliberately loose — a leading `v` and a digit — because the
// question here is only "did somebody pin this deliberately", and a project
// whose tags are `release-3` is not tracking a branch.
func looksLikeVersionTag(ref string) bool {
	trimmed := strings.TrimPrefix(ref, "v")
	return trimmed != "" && trimmed[0] >= '0' && trimmed[0] <= '9'
}

// checkInstalledIntegrity re-computes every installed file's digest and reports
// what no longer matches.
//
// An installation whose destination is gone entirely collapses to one finding
// rather than one per recorded file, for the reason "nothing installed"
// collapses: the reader has one problem and one command, and a finding per file
// would hide that.
func checkInstalledIntegrity(root string, recorded *lockDocument) []finding {
	var findings []finding

	for _, asset := range recorded.Assets {
		for _, installation := range asset.Installations {
			if installation.Destination == memoryFileName {
				// The memory file is checked as a managed block, not as a
				// destination: several assets share one file, so a per-asset
				// digest over it would report every instruction whenever any
				// one of them changed.
				continue
			}

			scopeRoot, err := scopeRootFor(root, installation.Harness, manifest.Asset{
				ID: asset.ID, Type: asset.Type, Scope: installation.Scope,
			})
			if err != nil {
				continue
			}

			state, err := readInstalled(scopeRoot, installation.Destination)
			if err != nil {
				continue
			}

			reported := projectRelative(root, scopeRoot, installation.Destination)
			if !state.Present {
				findings = append(findings, finding{
					Asset: asset.ID, Path: reported, Severity: severityError,
					Problem: fmt.Sprintf("%s is recorded as installed and is not there", reported),
					Remedy:  "Run `harnaas install`.",
				})
				continue
			}
			if state.Digest == installation.InstalledDigest {
				continue
			}
			findings = append(findings, compareFiles(asset.ID, reported, installation, state)...)
		}
	}
	return findings
}

// compareFiles names which file of an installation changed, went missing, or
// was added.
//
// Naming the file is the whole reason per-file digests are recorded. "Something
// under this skill changed" sends the reader to diff a directory; "this file
// changed" does not.
func compareFiles(assetID, destination string, installation lockInstallation, state installedState) []finding {
	recorded := make(map[string]string, len(installation.Files))
	for _, file := range installation.Files {
		recorded[file.Path] = string(file.Digest)
	}
	present := make(map[string]string, len(state.Files))
	for _, file := range state.Files {
		present[file.Path] = string(file.Digest)
	}

	var findings []finding
	for path, digest := range recorded {
		found, exists := present[path]
		switch {
		case !exists:
			findings = append(findings, finding{
				Asset: assetID, Path: destination + "/" + path, Severity: severityError,
				Problem: fmt.Sprintf("%s is recorded as installed and is missing", path),
				Remedy:  "Run `harnaas install`.",
			})
		case found != digest:
			findings = append(findings, finding{
				Asset: assetID, Path: destination + "/" + path, Severity: severityError,
				Problem: fmt.Sprintf("%s was modified outside harnaas", path),
				Remedy:  "Run `harnaas install --force` to restore it, or keep the edit and stop declaring the asset.",
			})
		}
	}
	for path := range present {
		if _, exists := recorded[path]; exists {
			continue
		}
		findings = append(findings, finding{
			Asset: assetID, Path: destination + "/" + path, Severity: severityError,
			Problem: fmt.Sprintf("%s is inside a destination harnaas manages and is not part of the installation", path),
			Remedy:  "Move it elsewhere if it is yours, or run `harnaas install --force` to restore the destination.",
		})
	}
	return findings
}

// checkBridgeLine verifies that CLAUDE.md imports the memory file exactly once,
// and only where instruction content is installed.
//
// Without the line Claude Code never reads the block, so the content is
// installed, reported as installed, and has no effect — which is the silent
// no-op every rule in this design exists to prevent.
func checkBridgeLine(root string, recorded *lockDocument) []finding {
	instructions := 0
	for _, asset := range recorded.Assets {
		for _, installation := range asset.Installations {
			if installation.Destination == memoryFileName {
				instructions++
			}
		}
	}
	if instructions == 0 {
		return nil
	}

	content, err := readManagedFile(root, bridgeFileName)
	if err != nil {
		return nil
	}

	count := 0
	for _, line := range splitLinesKeepingEndings(content) {
		if matchesBridgeLine(string(line)) {
			count++
		}
	}

	switch {
	case count == 1:
		return nil
	case count == 0:
		return []finding{{
			Severity: severityError,
			Problem: fmt.Sprintf("%s does not import %s, so Claude Code never reads the installed instruction content",
				bridgeFileName, memoryFileName),
			Remedy: "Run `harnaas install`.",
		}}
	default:
		return []finding{{
			Severity: severityError,
			Problem:  fmt.Sprintf("%s imports %s %d times", bridgeFileName, memoryFileName, count),
			Remedy:   "Run `harnaas install`, which collapses the duplicates.",
		}}
	}
}

// checkManagedBlocks reports a block whose markers do not pair up, and a block
// whose content no longer matches what the recorded installations imply.
//
// Content outside the markers is never reported. The team owns those bytes, and
// a tool that complained about them would be a tool nobody keeps installed.
func checkManagedBlocks(root string, recorded *lockDocument) []finding {
	var findings []finding

	for _, block := range []managedBlock{instructionBlock, installedIgnoreBlock} {
		content, err := readManagedFile(root, block.file)
		if err != nil {
			continue
		}
		if _, err := locateManagedBlock(content, block); err != nil {
			findings = append(findings, finding{
				Severity: severityError,
				Problem:  err.Error(),
				Remedy:   fmt.Sprintf("Repair the markers in %s by hand, then run `harnaas install`.", block.file),
			})
		}
	}

	_ = recorded
	return findings
}

// plural picks a form, so a one-asset project does not read as though harnaas
// cannot count.
func plural(n int, one, many string) string {
	if n == 1 {
		return one
	}
	return many
}

package cli

import (
	"fmt"

	"github.com/spf13/cobra"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/jsonutil"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/manifest"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/paths"
)

const lintLong = `Check that what is installed still agrees with harnaas.json and
harnaas.lock.json, and that nothing has moved on upstream.

lint changes nothing. It reports what is wrong and the command or edit that
resolves it, leaving harnaas install as the single repair path.

The only state that passes is one where every source is pinned to a tag or a
commit and is current. An available update is an error, not a warning, and no
flag downgrades one — a warning CI tolerates indefinitely does not keep a
team's configuration current.

Exit status is 0 when nothing is wrong, 2 when there are error-severity
findings, and 1 when lint itself could not run.`

// lintOptions holds the flags `harnaas lint` accepts, each registered locally
// on the command because the root carries no persistent flags.
type lintOptions struct {
	// frozen checks the manifest against the lockfile alone: no installed file
	// is read and no request is made.
	frozen bool

	// offline runs every local check and skips every network one.
	offline bool

	// strict promotes warnings to errors for the exit status only.
	strict bool

	// refresh bypasses cached resolution results.
	refresh bool

	// asJSON emits the findings as a single document on stdout.
	asJSON bool
}

// newLintCmd builds `harnaas lint`.
func newLintCmd() *cobra.Command {
	opts := &lintOptions{}

	cmd := &cobra.Command{
		Use:   "lint",
		Short: "Check the installed assets against " + manifest.FileName,
		Long:  lintLong,
		Args:  cobra.NoArgs,
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runLint(cmd, opts)
		},
	}

	flags := cmd.Flags()
	flags.BoolVar(&opts.frozen, "frozen", false,
		"check the manifest against the lockfile alone, reading no installed file and making no request")
	flags.BoolVar(&opts.offline, "offline", false, "run every local check and skip every network one")
	flags.BoolVar(&opts.strict, "strict", false, "promote warnings to errors for the exit status")
	flags.BoolVar(&opts.refresh, "refresh", false, "ignore cached resolution results")
	flags.BoolVar(&opts.asJSON, "json", false, "emit the findings as a single JSON document")

	return cmd
}

// runLint performs every check the flags allow and reports what it found.
//
// Nothing here writes. That is the command's whole contract, and it is why the
// remedy on every finding is a command to run rather than something lint offers
// to do: install is the single repair path, so there is exactly one place where
// a mistake can destroy work.
func runLint(cmd *cobra.Command, opts *lintOptions) error {
	ctx := cmd.Context()

	root, err := paths.ProjectRoot(ctx)
	if err != nil {
		return err
	}

	report := &lintReport{}

	document, err := manifest.Load(ctx)
	if err != nil {
		// A manifest that will not load is one finding and suppresses every
		// check that depends on it. Reporting it and then reporting every asset
		// as uninstalled would bury the one problem under its own consequences.
		report.Findings = append(report.Findings, finding{
			Severity: severityError,
			Problem:  err.Error(),
			Remedy:   fmt.Sprintf("Correct %s, then run `harnaas lint` again.", manifest.FileName),
		})
		return finishLint(cmd, report, opts)
	}

	interpretation, err := manifest.Interpret(document)
	if err != nil {
		report.Findings = append(report.Findings, finding{
			Severity: severityError,
			Problem:  err.Error(),
			Remedy:   fmt.Sprintf("Correct %s, then run `harnaas lint` again.", manifest.FileName),
		})
		return finishLint(cmd, report, opts)
	}

	recorded, err := loadLock(root)
	if err != nil {
		// An unreadable lockfile is lint failing to run rather than a finding:
		// there is nothing to check against, and reporting "nothing is
		// installed" would be a conclusion drawn from a file harnaas could not
		// read.
		return err
	}

	report.Findings = append(report.Findings, lintChecks(root, interpretation, recorded, opts)...)

	if opts.frozen {
		report.Skipped = append(report.Skipped, "installed file integrity", "update detection")
	} else if opts.offline {
		report.Skipped = append(report.Skipped, "update detection")
	} else {
		// Update detection reaches the network, which this change does not
		// implement yet. Saying so is the same rule the offline path follows: a
		// clean report must never be mistaken for a complete one.
		report.Skipped = append(report.Skipped, "update detection")
	}

	return finishLint(cmd, report, opts)
}

// lintChecks runs the checks the flags allow, in a fixed order.
//
// Frozen mode stops after the checks that read only the manifest and the
// lockfile. That is what makes it usable on a fresh clone where nothing has
// been installed: it asks whether the lockfile still satisfies the manifest,
// which is a question about two committed files and nothing else.
func lintChecks(root string, interpretation *manifest.Interpretation, recorded *lockDocument, opts *lintOptions) []finding {
	declared := interpretation.Assets

	var findings []finding
	findings = append(findings, checkNotReproducible(declared, interpretation.Sources)...)
	findings = append(findings, checkRefDisagreement(declared, interpretation.Sources, recorded)...)

	if opts.frozen {
		findings = append(findings, checkDeclaredButNotInstalled(declared, recorded)...)
		findings = append(findings, checkRecordedButUndeclared(declared, recorded)...)
		return findings
	}

	if collapsed, nothing := checkNothingInstalled(declared, recorded); nothing {
		// Everything below would report the same absence once per asset.
		return append(findings, collapsed)
	}

	findings = append(findings, checkDeclaredButNotInstalled(declared, recorded)...)
	findings = append(findings, checkRecordedButUndeclared(declared, recorded)...)
	findings = append(findings, checkInstalledIntegrity(root, recorded)...)
	findings = append(findings, checkManagedBlocks(root, recorded)...)
	findings = append(findings, checkBridgeLine(root, recorded)...)
	return findings
}

// finishLint writes the report and returns the error that decides the exit
// status.
func finishLint(cmd *cobra.Command, report *lintReport, opts *lintOptions) error {
	report.sort()

	if err := writeLintReport(cmd, report, opts); err != nil {
		return err
	}

	errors, warnings := report.counts()
	if opts.strict {
		errors += warnings
	}
	if errors > 0 {
		return &LintFindingsError{Errors: errors}
	}
	return nil
}

// writeLintReport prints the findings, grouped by asset, or emits them as one
// JSON document.
func writeLintReport(cmd *cobra.Command, report *lintReport, opts *lintOptions) error {
	if opts.asJSON {
		encoded, err := jsonutil.Marshal(report)
		if err != nil {
			return fmt.Errorf("encode the lint report: %w", err)
		}
		if _, err := cmd.OutOrStdout().Write(encoded); err != nil {
			return fmt.Errorf("write the lint report: %w", err)
		}
		return nil
	}

	out := cmd.OutOrStdout()

	group := ""
	for _, found := range report.Findings {
		subject := found.Asset
		if subject == "" {
			subject = "project"
		}
		if subject != group {
			fmt.Fprintf(out, "\n%s\n", subject)
			group = subject
		}
		fmt.Fprintf(out, "  %s: %s\n", found.Severity, found.Problem)
		fmt.Fprintf(out, "    %s\n", found.Remedy)
	}

	errors, warnings := report.counts()
	fmt.Fprintln(out)
	if errors == 0 && warnings == 0 {
		fmt.Fprintln(out, "Everything installed agrees with the manifest and the lockfile.")
	} else {
		fmt.Fprintf(out, "%d %s, %d %s\n",
			errors, plural(errors, "error", "errors"), warnings, plural(warnings, "warning", "warnings"))
	}

	// Stated even on a clean run. A report that checked less than it could and
	// said nothing would let a green CI job mean "current" when it only means
	// "nothing local was wrong".
	for _, skipped := range report.Skipped {
		advisef(cmd, "Skipped: %s.\n", skipped)
	}
	for _, unchecked := range report.Unchecked {
		advisef(cmd, "Unchecked: %s.\n", unchecked)
	}

	return nil
}

